# 模型路由与降级实现
import asyncio
from typing import AsyncIterator
from langchain_openai import ChatOpenAI
from langchain_anthropic import ChatAnthropic

class ModelRouter:
    def __init__(self):
        self.models = {
            "primary": ChatOpenAI(model="gpt-4", timeout=30),
            "secondary": ChatAnthropic(model="claude-3", timeout=30),
            "fallback": ChatOpenAI(model="gpt-3.5-turbo", timeout=10),
            "local": ChatOpenAI(model="local-model", base_url="http://localhost:8080")
        }
        self.circuit_breaker = {}  # 熔断器

    async def invoke(self, messages: list, strategy: str = "cascade"):
        """调用模型，支持多种策略"""
        if strategy == "cascade":
            return await self._cascade_invoke(messages)
        elif strategy == "fastest":
            return await self._fastest_invoke(messages)
        elif strategy == "cheapest":
            return await self._cheapest_invoke(messages)

    async def _cascade_invoke(self, messages: list):
        """级联降级策略"""
        for name, model in self.models.items():
            if self._is_circuit_open(name):
                continue
            try:
                result = await asyncio.wait_for(
                    model.ainvoke(messages),
                    timeout=30
                )
                return result
            except Exception as e:
                self._record_failure(name)
                continue
        raise Exception("所有模型都不可用")

    def _is_circuit_open(self, model_name: str) -> bool:
        """检查熔断器是否打开"""
        if model_name not in self.circuit_breaker:
            return False
        failures, last_failure = self.circuit_breaker[model_name]
        if failures >= 3:  # 连续失败3次
            return True
        return False

    def _record_failure(self, model_name: str):
        """记录失败"""
        if model_name not in self.circuit_breaker:
            self.circuit_breaker[model_name] = (0, None)
        failures, _ = self.circuit_breaker[model_name]
        self.circuit_breaker[model_name] = (failures + 1, asyncio.get_event_loop().time())

# 流式调用
async def stream_with_fallback(router: ModelRouter, messages: list) -> AsyncIterator[str]:
    """带降级的流式调用"""
    for name, model in router.models.items():
        try:
            async for chunk in model.astream(messages):
                yield chunk.content
            return
        except Exception:
            continue
    raise Exception("流式调用失败")

# 使用示例
router = ModelRouter()

# 级联降级
result = await router.invoke(messages, strategy="cascade")

# 流式输出
async for chunk in stream_with_fallback(router, messages):
    print(chunk, end="", flush=True)
